ation": {"id": "doi:10.1038/s41598-025-95587-6", "doi": "https://doi.org/10.1038/s41598-025-95587-6", "is_oa": true, "landing_page_url": "https://doi.org/10.1038/s41598-025-95587-6", "pdf_url": "https://www.nature.com/articles/s41598-025-95587-6.pdf", "source": {"id": "https://openalex.org/S196734849", "display_name": "Scientific Reports", "issn_l": "2045-2322", "issn": ["2045-2322"], "is_oa": true, "is_in_doaj": true, "is_core": true, "listed_in": ["anvur-class-a", "anvur-scientific", "cwts-core", "doaj", "dongbi-c", "doyens", "jufo-1", "ki-jl-1", "medline", "norway-1", "poland-140", "russia-white-list-1", "vabb-shw"], "host_organization": "https://openalex.org/P4310319908", "host_organization_name": "Nature Portfolio", "host_organization_lineage": ["https://openalex.org/P4310319908", "https://openalex.org/P4310319965"], "host_organization_lineage_names": ["Nature Portfolio", "Springer Nature"], "type": "journal"}, "license": "cc-by-nc-nd", "license_id": "https://openalex.org/licenses/cc-by-nc-nd", "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "Scientific Reports", "raw_type": "journal-article"}, "abstract": "There is a growing interest in understanding the effects of human-machine interaction on moral decision-making (Moral-DM) and sense of agency (SoA). Here, we investigated whether the \"moral behavior\" of an AI may affect both moral-DM and SoA in a military population, by using a task in which cadets played the role of drone operators on a battlefield. Participants had to decide whether or not to initiate an attack based on the presence of enemies and the risk of collateral damage. By combining three different types of trials (Moral vs. two No-Morals) in three blocks with three type of intelligent system support (No-AI support vs. Aggressive-AI vs. Conservative-AI), we showed that participants' decisions in the morally challenging situations were influenced by the inputs provided by the autonomous system. Furthermore, by measuring implicit and explicit agency, we found a significant increase in the SoA at the implicit level in the morally challenging situations, and a decrease in the explicit responsibility during the interaction with both AIs. These results suggest that the AI behavior influences human moral decision-making and alters the sense of agency and responsibility in ethical scenarios. These findings have implications for the design of AI-assisted decision-making processes in moral contexts."}]", "excerpt_truncated": true, "source_sha256": "8260ac223710d360985e259cfe05e2875ba70e0c8915b782733de9b6c6de8a59", "verification_required": true, "topic_domain": "responsibility_formation", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.1007/s11948-017-9943-x", "doi:10.1007/s11948-017-9943-x.pdf", "doi:10.1038/s41598-025-95587-6", "openalex:W2738218048"], "source_candidates": ["https://doi.org/10.1007/s11948-017-9943-x", "https://link.springer.com/content/pdf/10.1007/s11948-017-9943-x.pdf", "https://doi.org/10.1038/s41598-025-95587-6", "https://www.nature.com/articles/s41598-025-95587-6.pdf"], "source_candidate_identities": {}}
